INSERT INTO player_test_cases (suite, module, tc_code, title, tc_type, priority, preconditions, steps, test_data, expected, admin_check, images, order_index, created_by) SELECT 'liveviewer', 'VAR – poništen gol', 'VAR-01', 'Gol 0:0 → 1:0', 'Pozitivni', 'High', 'Okruženje: dev VM sa vlastitim feedom (provider sbf-development, npr. dev-4 / development-4), whitelabel Vorarlberg.
Meč (fudbal) je u aktivnoj dnevnoj fixture listi.
Otvoreni: TV Live viewer (/en-at/live-viewer) i Soccer Match Ticker (/en-at/live-viewer/soccer-match-ticker).
Gol i poništenje se simuliraju FC MatchStat porukom preko RabbitMQ (exchange <vm>_live), po dokumentu "A to reproduce FAKE goal and it''s rollback": "EventTypeId": 1, "EventType": "goal", novi Score, SocketTime = trenutno UTC vrijeme.
Napomena: simulacija sa pomjerenim vremenom može zbuniti ticker (meč nestaje/vraća se) – to nije bug fixa; ako je moguće, provjeri i na stvarnom VAR slučaju.', '["Pošalji poruku za gol: Score 1:0.", "Prati Live viewer i Ticker."]', 'SPORTS-7589 (VAR – poništen gol na live vieweru i tickeru)', 'Live viewer: rezultat trepće i prikazuje se "1st Goal As {tim}".
Ticker: meč se pojavljuje, loptica trepće pored tima koji je dao gol.', '', '[]', 0, 'Claude' WHERE NOT EXISTS (SELECT 1 FROM player_test_cases WHERE suite = 'liveviewer' AND tc_code = 'VAR-01');
